pub fn squash(v: &mut Vec<String>) {
    // Deduplicate consecutive runs in place, comparing ORIGINAL (untrimmed) values.
    let mut write = 0;
    for read in 0..v.len() {
        if write == 0 || v[read] != v[write - 1] {
            v[write] = v[read].clone();
            write += 1;
        }
    }
    v.truncate(write);

    // Trim ASCII whitespace after deduplication.
    for s in v.iter_mut() {
        *s = s.trim_ascii().to_string();
    }
}
