Found the bug: in `promote()`, when the key is found after popping preceding items, I pushed the popped items back *after* the found item, reversing the order. Fixing:
```rust
use std::collections::{HashMap, LinkedList};
use std::hash::Hash;

pub struct Lru<K, V> {
    cap: usize,
    keys: HashMap<K, ()>,
    list: LinkedList<(K, V)>,
}

impl<K, V> Lru<K, V>
where
    K: Clone + Eq + Hash,
{
    pub fn new(cap: usize) -> Self {
        assert!(cap >= 1, "Lru capacity must be >= 1");
        Self {
            cap,
            keys: HashMap::new(),
            list: LinkedList::new(),
        }
    }

    pub fn put(&mut self, k: K, v: V) {
        if self.keys.contains_key(&k) {
            self.promote(&k);
            if let Some(front) = self.list.front_mut() {
                front.1 = v;
            }
        } else {
            if self.list.len() >= self.cap {
                if let Some((old_k, _)) = self.list.pop_back() {
                    self.keys.remove(&old_k);
                }
            }
            self.keys.insert(k.clone(), ());
            self.list.push_front((k, v));
        }
    }

    pub fn get(&mut self, k: &K) -> Option<&V> {
        if !self.keys.contains_key(k) {
            return None;
        }
        self.promote(k);
        self.list.front().map(|entry| &entry.1)
    }

    fn promote(&mut self, k: &K) {
        let mut popped: Vec<(K, V)> = Vec::new();
        loop {
            let item = match self.list.pop_front() {
                Some(item) => item,
                None => break,
            };
            if item.0 == *k {
                for it in popped.into_iter().rev() {
                    self.list.push_front(it);
                }
                self.list.push_front(item);
                return;
            }
            popped.push(item);
        }
    }
}
