use std::sync::Arc;
use std::thread;

pub fn parallel_map<T, R, F>(mut items: Vec<T>, f: F, workers: usize) -> Vec<R>
where
    T: Send + 'static,
    R: Send + 'static,
    F: Fn(T) -> R + Send + Sync + 'static,
{
    let len = items.len();
    let base = len / workers;
    let rem = len % workers;

    let f = Arc::new(f);
    let mut handles = Vec::with_capacity(workers);

    for w in 0..workers {
        // Worker `w` gets `count` elements; the first `rem` workers get one extra.
        let count = if w < rem { base + 1 } else { base };

        // Peel this worker's contiguous slice off the front (owned, moved in).
        // The last worker takes whatever remains.
        let chunk: Vec<T> = if w + 1 == workers {
            items
        } else {
            items.drain(..count).collect()
        };

        let f = Arc::clone(&f);
        handles.push(thread::spawn(move || {
            let mut out = Vec::with_capacity(chunk.len());
            for x in chunk {
                out.push(f(x));
            }
            out
        }));
    }

    // Join in spawn order; each worker already produced its slice in input order.
    let mut results = Vec::with_capacity(len);
    for h in handles {
        results.extend(h.join().expect("parallel_map worker thread panicked"));
    }
    results
}
