use std::marker::PhantomData;

pub struct PairsMut<'a, T> {
    ptr: *mut T,
    len: usize,
    _marker: PhantomData<&'a mut [T]>,
}

impl<'a, T> Iterator for PairsMut<'a, T> {
    type Item = (&'a mut T, &'a mut T);

    fn next(&mut self) -> Option<Self::Item> {
        if self.len < 2 {
            return None;
        }
        // `ptr` and `ptr.add(1)` point into disjoint regions of the original
        // slice, so the two mutable references cannot alias.
        let first = unsafe { &mut *self.ptr };
        let second = unsafe { &mut *self.ptr.add(1) };
        self.ptr = self.ptr.add(2);
        self.len -= 2;
        Some((first, second))
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let n = self.len / 2;
        (n, Some(n))
    }
}

impl<T> ExactSizeIterator for PairsMut<'_, T> {
    fn len(&self) -> usize {
        self.len / 2
    }
}

pub fn pairs_mut<T>(s: &mut [T]) -> PairsMut<'_, T> {
    PairsMut {
        ptr: s.as_mut_ptr(),
        len: s.len(),
        _marker: PhantomData,
    }
}
