use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Wake, Waker};
use std::thread;

/// A future that returns `Pending` (and wakes) once for each remaining tick,
/// then completes.
pub struct YieldNow {
    pub remaining: u32,
}

impl Future for YieldNow {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let this = self.get_mut();
        if this.remaining > 0 {
            this.remaining -= 1;
            cx.waker().wake_by_ref();
            Poll::Pending
        } else {
            Poll::Ready(())
        }
    }
}

/// State shared between `block_on` and its waker.
struct SharedWaker {
    /// Set by the waker; consumed by the polling thread.
    woken: AtomicBool,
    /// The thread running `block_on`, so `wake()` can unpark it from
    /// any thread.
    parked_thread: Mutex<Option<thread::Thread>>,
}

impl SharedWaker {
    fn wake_impl(state: &SharedWaker) {
        // Release: publishes any state the waker's owner wrote before waking.
        state.woken.store(true, Ordering::Release);
        // Unpark the blocked thread (or leave a permit if it hasn't parked yet).
        if let Some(t) = state.parked_thread.lock().unwrap().as_ref() {
            t.unpark();
        }
    }
}

impl Wake for SharedWaker {
    fn wake(self: Arc<Self>) {
        Self::wake_impl(&self);
    }

    fn wake_by_ref(self: &Arc<Self>) {
        Self::wake_impl(self);
    }
}

/// Polls `fut` to completion on the current thread.
///
/// When `fut` yields `Pending`, the thread parks until the future's waker is
/// invoked (possibly from another thread), then polls again.
pub fn block_on<F: Future>(mut fut: F) -> F::Output {
    let state = Arc::new(SharedWaker {
        woken: AtomicBool::new(false),
        parked_thread: Mutex::new(None),
    });

    // Register the current thread so wake() can unpark it.
    *state.parked_thread.lock().unwrap() = Some(thread::current());

    let waker = Waker::from(state.clone());

    // `fut` is owned here, pinned on the stack, and never moved again.
    let mut fut = unsafe { Pin::new_unchecked(&mut fut) };

    loop {
        match fut.as_mut().poll(&mut Context::from_waker(&waker)) {
            Poll::Ready(value) => return value,
            Poll::Pending => {
                // Block until the waker fires. A concurrent wake() is safe:
                // it either sets the flag (observed here) or leaves an unpark
                // permit so park() returns immediately — no lost wakeups.
                while !state.woken.swap(false, Ordering::Acquire) {
                    thread::park();
                }
            }
        }
    }
}
